const FOLLOW_UP = /^(а |и |ну |да,? |ок,? |хорошо,? )?(сколько|скок|цена|стоит|почём|почем|есть|наличи|можно|когда|где|какой|какая|какие|такой|такая|это|эта|этот|его|её|их|подойд|подход|доставк|срок)/i;
