    for (const code of codes) if (hasCode(hay, code)) s += 5;
    for (const q of mainWords) s += nw.some(w => sameWord(q, w)) ? 2 : (dw.some(w => sameWord(q, w)) ? 1 : 0);
    for (const q of ctxWords) s += nw.some(w => sameWord(q, w)) ? 1 : 0;
